package org.apache.commons.math3.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Fraction_divide_TriageGen1Test {

    @Test
    public void testDivide_SuccessfulDivision() {
        // Test case: (1/2) / (3/4) = 1/2 * 4/3 = 4/6 = 2/3
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(3, 4);
        Fraction expected = new Fraction(2, 3);
        Fraction result = f1.divide(f2);

        assertEquals("The division result should be 2/3", expected, result);
    }










}

