public class Fraction_divide_TriageGen1Test {



    @Test
    public void testDivide_DivideByOne() {
        // Test case: (5/8) / (1/1) = 5/8
        Fraction f1 = new Fraction(5, 8);
        Fraction f2 = new Fraction(1, 1);
        Fraction expected = new Fraction(5, 8);
        Fraction result = f1.divide(f2);

        assertEquals("Dividing by 1 should return the same fraction", expected, result);
